import { expect, test } from 'bun:test';
import { createIsolatedTerminal } from './test-helpers';

test('repeated output and reflow resize completes with reused WASM pages', async () => {
  const terminal = await createIsolatedTerminal({ cols: 80, rows: 35, scrollback: 10_000 });
  terminal.open(document.createElement('div'));
  (terminal as any).cancelRenderLoop();

  const block = Array.from(
    { length: 120 },
    (_, row) =>
      `\x1b[48;5;${row % 256}m${String(row).padStart(4, '0')}:${'x'.repeat(180)}\x1b[0m\r\n`
  ).join('');

  for (const [cols, rows] of [
    [53, 71],
    [126, 34],
    [131, 36],
  ]) {
    terminal.write(block);
    terminal.resize(cols, rows);
  }

  expect(terminal.cols).toBe(131);
  expect(terminal.rows).toBe(36);
  expect(terminal.wasmTerm!.getScrollbackLength()).toBeGreaterThan(0);
  terminal.dispose();
});

import { expect, test } from 'bun:test';
import { Ghostty } from './ghostty';

test('Ghostty rasterizes its built-in block and Powerline sprites', async () => {
  const ghostty = await Ghostty.load();
  const width = 11;
  const height = 19;

  expect(ghostty.hasSpriteCodepoint(0x41)).toBe(false);
  expect(ghostty.rasterizeSprite(0x41, width, height, 2)).toBeNull();

  for (const codepoint of [0x2588, 0xe0b0, 0xe0b4, 0xe0b6]) {
    expect(ghostty.hasSpriteCodepoint(codepoint)).toBe(true);
    const bitmap = ghostty.rasterizeSprite(codepoint, width, height, 2);
    expect(bitmap).not.toBeNull();
    expect(bitmap?.width).toBe(width);
    expect(bitmap?.height).toBe(height);
    expect(bitmap?.pixels).toHaveLength(width * height);
    expect(bitmap?.pixels.some((pixel) => pixel !== 0)).toBe(true);
  }
});

/**
 * URL Detection Tests
 *
 * Tests for the UrlRegexProvider to ensure plain text URLs
 * are correctly detected and made clickable.
 */

import { describe, expect, test } from 'bun:test';
import { UrlRegexProvider } from './providers/url-regex-provider';
import type { ILink } from './types';

/**
 * Mock terminal for testing
 */
function createMockTerminal(lineText: string) {
  const cells = Array.from(lineText).map((char) => ({
    getCodepoint: () => char.codePointAt(0) || 0,
  }));

  return {
    buffer: {
      active: {
        getLine: (y: number) => {
          if (y !== 0) return undefined;
          return {
            length: cells.length,
            getCell: (x: number) => cells[x],
          };
        },
      },
    },
  };
}

/**
 * Helper to get links from provider
 */
function getLinks(lineText: string): Promise<ILink[] | undefined> {
  const terminal = createMockTerminal(lineText) as any;
  const provider = new UrlRegexProvider(terminal);

  return new Promise((resolve) => {
    provider.provideLinks(0, resolve);
  });
}

describe('URL Detection', () => {
  test('detects HTTPS URLs', async () => {
    const links = await getLinks('Visit https://github.com for code');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('https://github.com');
    expect(links?.[0].range.start.x).toBe(6);
    // End is inclusive - last character is at index 23 (https://github.com is 19 chars, starts at 6)
    expect(links?.[0].range.end.x).toBe(23);
  });

  test('detects HTTP URLs', async () => {
    const links = await getLinks('Check http://example.com');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('http://example.com');
  });

  test('detects mailto: links', async () => {
    const links = await getLinks('Email: mailto:test@example.com');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('mailto:test@example.com');
  });

  test('detects ssh:// URLs', async () => {
    const links = await getLinks('Connect via ssh://user@server.com');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('ssh://user@server.com');
  });

  test('detects git:// URLs', async () => {
    const links = await getLinks('Clone git://github.com/repo.git');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('git://github.com/repo.git');
  });

  test('detects ftp:// URLs', async () => {
    const links = await getLinks('Download ftp://files.example.com/file');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('ftp://files.example.com/file');
  });

  test('strips trailing period', async () => {
    const links = await getLinks('Check https://example.com.');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('https://example.com');
    // Should NOT include the trailing period
    expect(links?.[0].text.endsWith('.')).toBe(false);
  });

  test('strips trailing comma', async () => {
    const links = await getLinks('See https://example.com, or else');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('https://example.com');
  });

  test('strips trailing parenthesis', async () => {
    const links = await getLinks('(see https://example.com)');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('https://example.com');
  });

  test('strips trailing exclamation', async () => {
    const links = await getLinks('Visit https://example.com!');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('https://example.com');
  });

  test('handles multiple URLs on same line', async () => {
    const links = await getLinks('https://a.com and https://b.com');
    expect(links).toBeDefined();
    expect(links?.length).toBe(2);
    expect(links?.[0].text).toBe('https://a.com');
    expect(links?.[1].text).toBe('https://b.com');
  });

  test('returns undefined when no URL present', async () => {
    const links = await getLinks('No URLs here');
    expect(links).toBeUndefined();
  });

  test('handles URLs with query parameters', async () => {
    const links = await getLinks('https://example.com?foo=bar&baz=qux');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('https://example.com?foo=bar&baz=qux');
  });

  test('handles URLs with fragments', async () => {
    const links = await getLinks('https://example.com/page#section');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('https://example.com/page#section');
  });

  test('handles URLs with ports', async () => {
    const links = await getLinks('https://example.com:8080/path');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('https://example.com:8080/path');
  });

  test('does not detect file paths', async () => {
    const links = await getLinks('/home/user/file.txt');
    expect(links).toBeUndefined();
  });

  test('does not detect relative paths', async () => {
    const links = await getLinks('./relative/path');
    expect(links).toBeUndefined();
  });

  test('link has activate function', async () => {
    const links = await getLinks('https://example.com');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(typeof links?.[0].activate).toBe('function');
  });

  test('detects tel: URLs', async () => {
    const links = await getLinks('Call tel:+1234567890');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toBe('tel:+1234567890');
  });

  test('detects magnet: URLs', async () => {
    const links = await getLinks('Download magnet:?xt=urn:btih:abc123');
    expect(links).toBeDefined();
    expect(links?.length).toBe(1);
    expect(links?.[0].text).toContain('magnet:?xt=urn:btih:abc123');
  });
});

/**
 * Test Helpers for ghostty-web
 *
 * Provides utilities for test isolation and setup.
 */

import { Ghostty } from './ghostty';
import type { ITerminalOptions } from './interfaces';
import { Terminal } from './terminal';

/**
 * Creates a Terminal instance with an isolated Ghostty WASM instance.
 * This ensures complete test isolation with no shared state between tests.
 *
 * @param options - Terminal options (cols, rows, etc.)
 * @returns Promise resolving to Terminal instance
 *
 * @example
 * ```typescript
 * import { createIsolatedTerminal } from './test-helpers';
 *
 * describe('My Tests', () => {
 *   test('my test', async () => {
 *     const term = await createIsolatedTerminal({ cols: 80, rows: 24 });
 *     term.open(container);
 *     // ... test logic ...
 *     term.dispose();
 *   });
 * });
 * ```
 */
export async function createIsolatedTerminal(
  options: Omit<ITerminalOptions, 'ghostty'> = {}
): Promise<Terminal> {
  const ghostty = await Ghostty.load();
  return new Terminal({ ...options, ghostty });
}

/**
 * Minimal self-contained reproduction of WASM viewport/ring-buffer corruption.
 *
 * BUG: Writing escape-heavy output (~68 lines with SGR sequences) repeatedly
 * to a terminal causes the internal circular buffer to misindex after ~8 reps.
 *
 * Symptoms:
 * 1. getScrollbackLength() drops unexpectedly (e.g., 498 → 269) — the ring
 *    buffer's row tracking becomes incorrect.
 * 2. At certain column widths, getViewport() returns corrupted data where
 *    content from different lines is horizontally merged into one row.
 * 3. Both getViewport() and getLine() return the same wrong data.
 *
 * The corruption depends on column width (NOT data content):
 * - cols=80: OK    cols=120: CORRUPT    cols=130: CORRUPT
 * - cols=140: OK   cols=160: scrollback drops but viewport appears OK
 *   (row merge lands on empty rows)
 *
 * This is 100% self-contained — no external fixture files needed.
 */

import { describe, expect, test } from 'bun:test';
import { createIsolatedTerminal } from './test-helpers';
import type { Terminal } from './terminal';

const ESC = '\x1b';

/**
 * Generate escape-heavy terminal output similar to a color test script.
 * Produces ~68 lines with SGR 1/3/4/7, 256-color, and truecolor sequences.
 */
function generateTestOutput(): Uint8Array {
  const lines: string[] = [];

  // Bold banner with Unicode box-drawing characters
  lines.push(`${ESC}[1m${'═'.repeat(80)}${ESC}[0m`);
  lines.push('');

  // Section 1: 256-color palette blocks (8 rows of 32 colors)
  lines.push(`${ESC}[1m── COLORS ──${ESC}[0m`);
  for (let row = 0; row < 8; row++) {
    let line = '';
    for (let i = 0; i < 32; i++) {
      const idx = row * 32 + i;
      line += `${ESC}[48;5;${idx}m  ${ESC}[0m`;
    }
    lines.push(line);
  }

  // Section 2: Truecolor gradients (6 rows of 80 colored cells)
  lines.push(`${ESC}[1m── GRADIENTS ──${ESC}[0m`);
  for (let row = 0; row < 6; row++) {
    let line = '';
    for (let i = 0; i < 80; i++) {
      const r = Math.floor(Math.sin(i * 0.08 + row) * 127 + 128);
      const g = Math.floor(Math.sin(i * 0.08 + row + 2) * 127 + 128);
      const b = Math.floor(Math.sin(i * 0.08 + row + 4) * 127 + 128);
      line += `${ESC}[48;2;${r};${g};${b}m ${ESC}[0m`;
    }
    lines.push(line);
  }

  // Section 3: Text attributes
  lines.push(`${ESC}[1m── ATTRIBUTES ──${ESC}[0m`);
  lines.push(`  ${ESC}[1mBold${ESC}[0m ${ESC}[3mItalic${ESC}[0m ${ESC}[4mUnderline${ESC}[0m ${ESC}[7mReverse${ESC}[0m`);

  // Section 4: Unicode box drawing
  lines.push(`${ESC}[1m── UNICODE ──${ESC}[0m`);
  lines.push('  ┌──────────┬──────────┐');
  lines.push('  │  Cell A   │  Cell B   │');
  lines.push('  ├──────────┼──────────┤');
  lines.push('  │  Cell C   │  Cell D   │');
  lines.push('  └──────────┴──────────┘');

  // Sections 5-8: More colored text to reach ~68 lines
  for (let section = 0; section < 4; section++) {
    lines.push(`${ESC}[1m── SECTION ${section + 5} ──${ESC}[0m`);
    for (let row = 0; row < 8; row++) {
      let line = '  ';
      for (let i = 0; i < 60; i++) {
        const idx = (section * 64 + row * 8 + i) % 256;
        line += `${ESC}[38;5;${idx}m*${ESC}[0m`;
      }
      lines.push(line);
    }
  }

  // Final banner
  lines.push('');
  lines.push('═'.repeat(80));
  lines.push('  ✓ Test complete');
  lines.push('═'.repeat(80));
  lines.push('');

  return new TextEncoder().encode(lines.join('\r\n') + '\r\n');
}

function getViewportText(term: Terminal): string[] {
  const viewport = term.wasmTerm!.getViewport();
  const cols = term.cols;
  const rows: string[] = [];
  for (let row = 0; row < term.rows; row++) {
    let text = '';
    for (let col = 0; col < cols; col++) {
      const c = viewport[row * cols + col];
      if (c.width === 0) continue;
      text += c.codepoint > 32 ? String.fromCodePoint(c.codepoint) : ' ';
    }
    rows.push(text.trimEnd());
  }
  return rows;
}

describe('WASM ring buffer corruption — self-contained reproduction', () => {
  const data = generateTestOutput();

  /**
   * PRIMARY BUG INDICATOR: scrollbackLength should increase monotonically
   * when writing the same data repeatedly. The ring buffer corruption
   * causes it to jump backwards.
   */
  test('scrollbackLength increases monotonically after repeated writes', async () => {
    const term = await createIsolatedTerminal({ cols: 160, rows: 39, scrollback: 10000 });
    const container = document.createElement('div');
    term.open(container);

    const sbLengths: number[] = [];
    for (let rep = 0; rep < 12; rep++) {
      term.write(data);
      term.wasmTerm!.update();
      sbLengths.push(term.wasmTerm!.getScrollbackLength());
    }

    console.log('Scrollback lengths:', sbLengths);

    // Find non-monotonic drops
    let drops = 0;
    for (let i = 1; i < sbLengths.length; i++) {
      if (sbLengths[i] < sbLengths[i - 1]) {
        drops++;
        console.log(`Drop at rep ${i}: ${sbLengths[i-1]} → ${sbLengths[i]} (delta ${sbLengths[i] - sbLengths[i-1]})`);
      }
    }

    // Scrollback should never decrease when writing new data
    expect(drops).toBe(0);
    term.dispose();
  });

  /**
   * Viewport text should remain stable across repeated writes.
   * The old bug caused catastrophic row-merging (many rows corrupted at early reps).
   * After the fix, at most 1 row may show a trivial trailing-whitespace diff.
   */
  test('viewport text remains stable at cols=130 after repeated writes', async () => {
    const term = await createIsolatedTerminal({ cols: 130, rows: 39, scrollback: 10000 });
    const container = document.createElement('div');
    term.open(container);

    let baseline: string[] | null = null;
    let maxDiffRows = 0;

    for (let rep = 0; rep < 12; rep++) {
      term.write(data);
      term.wasmTerm!.update();
      const text = getViewportText(term);

      if (!baseline) {
        baseline = text;
      } else {
        let diffs = 0;
        for (let i = 0; i < Math.max(text.length, baseline.length); i++) {
          if ((text[i] || '') !== (baseline[i] || '')) {
            diffs++;
          }
        }
        if (diffs > maxDiffRows) maxDiffRows = diffs;
      }
    }

    // The old bug caused 10+ rows of corruption at early reps.
    // After the fix, at most 1 row may differ (trailing whitespace artifact).
    console.log(`Max diff rows across reps: ${maxDiffRows}`);
    expect(maxDiffRows).toBeLessThanOrEqual(1);
    term.dispose();
  });

  /**
   * getViewport and getLine agree — corruption is in the underlying
   * WASM state, not just in one API.
   */
  test('getViewport and getLine return identical (corrupted) data', async () => {
    const term = await createIsolatedTerminal({ cols: 130, rows: 39, scrollback: 10000 });
    const container = document.createElement('div');
    term.open(container);

    for (let rep = 0; rep < 12; rep++) {
      term.write(data);
      term.wasmTerm!.update();
    }

    const vpText = getViewportText(term);
    let matches = 0;
    for (let row = 0; row < term.rows; row++) {
      const line = term.wasmTerm?.getLine(row);
      if (!line) continue;
      const lnText = line.map(c => String.fromCodePoint(c.codepoint || 32)).join('').trimEnd();
      if (vpText[row] === lnText) matches++;
    }

    console.log(`${matches}/${term.rows} viewport rows match getLine`);
    expect(matches).toBe(term.rows);
    term.dispose();
  });

  /**
   * Column width affects whether the corruption is visible in viewport text.
   * The ring buffer always corrupts, but row merging is only detectable when
   * the misaligned rows contain different content.
   */
  test('column width sensitivity', async () => {
    const results: string[] = [];
    for (const cols of [80, 100, 120, 130, 140, 160]) {
      const term = await createIsolatedTerminal({ cols, rows: 39, scrollback: 10000 });
      const container = document.createElement('div');
      term.open(container);

      const sbLengths: number[] = [];
      let baseline: string[] | null = null;
      let vpCorrupt = false;

      for (let rep = 0; rep < 12; rep++) {
        term.write(data);
        term.wasmTerm!.update();
        sbLengths.push(term.wasmTerm!.getScrollbackLength());
        const text = getViewportText(term);
        if (!baseline) { baseline = text; }
        else {
          for (let i = 0; i < Math.max(text.length, baseline.length); i++) {
            if ((text[i] || '') !== (baseline[i] || '')) { vpCorrupt = true; break; }
          }
        }
      }

      let sbDrops = 0;
      for (let i = 1; i < sbLengths.length; i++) {
        if (sbLengths[i] < sbLengths[i - 1]) sbDrops++;
      }

      const line = `cols=${cols}: scrollback_drops=${sbDrops} viewport_corrupt=${vpCorrupt}`;
      results.push(line);
      console.log(line);
      term.dispose();
    }
  });
});

/**
 * Viewport row-merging bug — self-contained reproduction.
 *
 * BUG: After writing enough escape-heavy output to accumulate scrollback,
 * getViewport() periodically returns corrupted data where content from
 * two rows is horizontally concatenated into a single row.
 *
 * Properties:
 * - Transient: self-corrects on the next write (not consecutive)
 * - Periodic: recurs at a fixed interval (~11 writes at cols=160 with this data)
 * - All column widths affected, just at different frequencies
 * - Independent of scrollback capacity (identical at 10KB..50MB)
 * - In WASM state: both getViewport() and getLine() return the same wrong data
 *
 * The trigger requires enough per-write byte volume (~20KB+) to advance
 * the ring buffer sufficiently. Smaller output (~3KB) only triggers the
 * bug at narrow widths (cols≈120-130); larger output triggers it everywhere.
 *
 * 100% self-contained — no external fixture files needed.
 */

import { describe, expect, test } from 'bun:test';
import { createIsolatedTerminal } from './test-helpers';
import type { Terminal } from './terminal';

const ESC = '\x1b';

/**
 * Generate ~25KB of escape-heavy terminal output. Must be large enough
 * to trigger the ring buffer misalignment at common widths (cols=160).
 *
 * The output simulates a color/rendering test script with:
 * - 256-color palette blocks (SGR 48;5;N)
 * - Truecolor gradients (SGR 48;2;R;G;B)
 * - Text attribute combinations (bold, italic, underline, reverse)
 * - Unicode box drawing
 * - Dense colored grids (8 sections × 8 rows × 70 cols)
 */
function generateOutput(): Uint8Array {
  const lines: string[] = [];

  lines.push(`${ESC}[1m${'═'.repeat(80)}${ESC}[0m`);
  lines.push(`${ESC}[1m  Terminal Rendering Test${ESC}[0m`);
  lines.push(`${ESC}[1m${'═'.repeat(80)}${ESC}[0m`);
  lines.push('');

  // 256-color palette
  lines.push(`${ESC}[1m── 1. 256-COLOR PALETTE ──${ESC}[0m`);
  for (let row = 0; row < 8; row++) {
    let line = '  ';
    for (let i = 0; i < 32; i++) {
      line += `${ESC}[48;5;${row * 32 + i}m  ${ESC}[0m`;
    }
    lines.push(line);
  }
  lines.push('');

  // Truecolor gradients
  lines.push(`${ESC}[1m── 2. TRUECOLOR GRADIENTS ──${ESC}[0m`);
  for (let row = 0; row < 8; row++) {
    let line = '  ';
    for (let i = 0; i < 80; i++) {
      const r = Math.floor(Math.sin(i * 0.08 + row) * 127 + 128);
      const g = Math.floor(Math.sin(i * 0.08 + row + 2) * 127 + 128);
      const b = Math.floor(Math.sin(i * 0.08 + row + 4) * 127 + 128);
      line += `${ESC}[48;2;${r};${g};${b}m ${ESC}[0m`;
    }
    lines.push(line);
  }
  lines.push('');

  // Text attributes
  lines.push(`${ESC}[1m── 3. TEXT ATTRIBUTES ──${ESC}[0m`);
  lines.push(`  ${ESC}[1mBold${ESC}[0m  ${ESC}[3mItalic${ESC}[0m  ${ESC}[4mUnderline${ESC}[0m  ${ESC}[7mReverse${ESC}[0m  ${ESC}[9mStrike${ESC}[0m`);
  lines.push(`  ${ESC}[1;3mBold+Italic${ESC}[0m  ${ESC}[1;4mBold+Under${ESC}[0m  ${ESC}[3;4mItalic+Under${ESC}[0m`);
  lines.push('');

  // Unicode box drawing
  lines.push(`${ESC}[1m── 4. UNICODE BOX DRAWING ──${ESC}[0m`);
  lines.push('  ┌──────────┬──────────┬──────────┐');
  lines.push('  │  Cell A   │  Cell B   │  Cell C   │');
  lines.push('  ├──────────┼──────────┼──────────┤');
  lines.push('  │  Cell D   │  Cell E   │  Cell F   │');
  lines.push('  └──────────┴──────────┴──────────┘');
  lines.push('');

  // Dense colored grids — this is the bulk, producing enough byte volume
  for (let section = 0; section < 8; section++) {
    lines.push(`${ESC}[1m── ${section + 5}. COLOR GRID ${String.fromCharCode(65 + section)} ──${ESC}[0m`);
    for (let row = 0; row < 8; row++) {
      let line = '  ';
      for (let i = 0; i < 70; i++) {
        const idx = (section * 64 + row * 8 + i) % 256;
        if ((i + row) % 3 === 0) {
          line += `${ESC}[38;2;${(idx * 7) % 256};${(idx * 13) % 256};${(idx * 23) % 256}m*${ESC}[0m`;
        } else {
          line += `${ESC}[38;5;${idx}m*${ESC}[0m`;
        }
      }
      lines.push(line);
    }
    lines.push('');
  }

  lines.push(`${ESC}[1m${'═'.repeat(80)}${ESC}[0m`);
  lines.push(`  ${ESC}[32m✓${ESC}[0m Test complete`);
  lines.push(`${ESC}[1m${'═'.repeat(80)}${ESC}[0m`);
  lines.push('');

  return new TextEncoder().encode(lines.join('\r\n') + '\r\n');
}

/** Read viewport as text rows. */
function getViewportText(term: Terminal): string[] {
  const vp = term.wasmTerm!.getViewport();
  const cols = term.cols;
  const rows: string[] = [];
  for (let r = 0; r < term.rows; r++) {
    let text = '';
    for (let c = 0; c < cols; c++) {
      const cell = vp[r * cols + c];
      if (cell.width === 0) continue;
      text += cell.codepoint > 32 ? String.fromCodePoint(cell.codepoint) : ' ';
    }
    rows.push(text.trimEnd());
  }
  return rows;
}

/** Count rows that differ between two viewport snapshots. */
function countDiffs(a: string[], b: string[]): number {
  let n = 0;
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    if ((a[i] || '') !== (b[i] || '')) n++;
  }
  return n;
}

describe('Viewport row-merge bug', () => {
  const data = generateOutput();

  test('test data is large enough (>20KB)', () => {
    expect(data.length).toBeGreaterThan(20_000);
  });

  /**
   * Primary assertion: viewport text should be identical after every write
   * of the same data. The bug causes periodic corruption where rows are
   * horizontally merged.
   */
  test('viewport text is stable after repeated writes', async () => {
    const term = await createIsolatedTerminal({ cols: 160, rows: 39, scrollback: 10_000_000 });
    const container = document.createElement('div');
    term.open(container);

    let baseline: string[] | null = null;
    const corruptReps: number[] = [];

    for (let rep = 0; rep < 30; rep++) {
      term.write(data);
      term.wasmTerm!.update();
      const text = getViewportText(term);

      if (!baseline) {
        baseline = text;
      } else {
        if (countDiffs(text, baseline) > 0) corruptReps.push(rep);
      }
    }

    if (corruptReps.length > 0) {
      console.log(`Corrupt at reps: [${corruptReps.join(', ')}]`);
    }
    expect(corruptReps.length).toBe(0);

    term.dispose();
  });

  /**
   * The corruption is transient — it never appears on consecutive writes.
   * The write after a corrupt read always produces a correct viewport.
   */
  test('corruption is never consecutive', async () => {
    const term = await createIsolatedTerminal({ cols: 160, rows: 39, scrollback: 10_000_000 });
    const container = document.createElement('div');
    term.open(container);

    let baseline: string[] | null = null;
    let prevCorrupt = false;
    let consecutivePairs = 0;

    for (let rep = 0; rep < 30; rep++) {
      term.write(data);
      term.wasmTerm!.update();
      const text = getViewportText(term);

      if (!baseline) {
        baseline = text;
        prevCorrupt = false;
      } else {
        const corrupt = countDiffs(text, baseline) > 0;
        if (corrupt && prevCorrupt) consecutivePairs++;
        prevCorrupt = corrupt;
      }
    }

    expect(consecutivePairs).toBe(0);
    term.dispose();
  });

  /**
   * The corruption is independent of scrollback capacity. The same
   * writes corrupt at the same reps regardless of buffer size.
   */
  test('corruption pattern is identical across scrollback sizes', async () => {
    const patterns: string[] = [];

    for (const sb of [10_000, 1_000_000, 50_000_000]) {
      const term = await createIsolatedTerminal({ cols: 160, rows: 39, scrollback: sb });
      const container = document.createElement('div');
      term.open(container);

      let baseline: string[] | null = null;
      const corruptReps: number[] = [];

      for (let rep = 0; rep < 15; rep++) {
        term.write(data);
        term.wasmTerm!.update();
        const text = getViewportText(term);

        if (!baseline) baseline = text;
        else if (countDiffs(text, baseline) > 0) corruptReps.push(rep);
      }

      patterns.push(corruptReps.join(','));
      console.log(`scrollback=${sb}: corrupt at [${corruptReps.join(', ')}]`);
      term.dispose();
    }

    // All patterns should be identical
    expect(new Set(patterns).size).toBe(1);
  });

  /**
   * Verify no row corruption occurs over many writes (regression guard).
   * Previously, rows showed horizontally merged content from stale page cells.
   */
  test('no row corruption over extended writes', async () => {
    const term = await createIsolatedTerminal({ cols: 160, rows: 39, scrollback: 10_000_000 });
    const container = document.createElement('div');
    term.open(container);

    let baseline: string[] | null = null;
    let corruptCount = 0;

    for (let rep = 0; rep < 30; rep++) {
      term.write(data);
      term.wasmTerm!.update();
      const text = getViewportText(term);

      if (!baseline) { baseline = text; continue; }
      if (countDiffs(text, baseline) > 0) corruptCount++;
    }

    expect(corruptCount).toBe(0);

    term.dispose();
  });

  /**
   * WORKAROUND: Replace every ESC[0m (SGR reset) with ESC[0;48;2;R;G;Bm
   * where R,G,B is the terminal's background color. This keeps bg_color
   * set to a non-.none value at all times, which triggers the row-clear
   * path in cursorDownScroll even in the unpatched WASM code.
   *
   * The visual result is identical — the explicit bg color matches the
   * terminal default — but the internal state differs enough to prevent
   * stale cells from surviving page growth.
   */
  test('workaround: replacing ESC[0m with ESC[0;48;2;bg;bg;bgm prevents corruption', async () => {
    const term = await createIsolatedTerminal({ cols: 160, rows: 39, scrollback: 10_000_000 });
    const container = document.createElement('div');
    term.open(container);

    // Theme bg for dark terminal: (10, 10, 10) — the default #0a0a0a
    const bgR = 10, bgG = 10, bgB = 10;
    const resetReplacement = new TextEncoder().encode(`\x1b[0;48;2;${bgR};${bgG};${bgB}m`);
    const resetSeq = new TextEncoder().encode('\x1b[0m');

    // Patch: replace every ESC[0m with ESC[0;48;2;R;G;Bm in the data
    function patchResets(src: Uint8Array): Uint8Array {
      // Find all occurrences of ESC[0m (bytes: 1B 5B 30 6D)
      const positions: number[] = [];
      for (let i = 0; i < src.length - 3; i++) {
        if (src[i] === 0x1B && src[i+1] === 0x5B && src[i+2] === 0x30 && src[i+3] === 0x6D) {
          positions.push(i);
        }
      }
      if (positions.length === 0) return src;

      const extra = resetReplacement.length - resetSeq.length;
      const out = new Uint8Array(src.length + positions.length * extra);
      let si = 0, di = 0;
      for (const pos of positions) {
        const chunk = src.subarray(si, pos);
        out.set(chunk, di);
        di += chunk.length;
        out.set(resetReplacement, di);
        di += resetReplacement.length;
        si = pos + resetSeq.length;
      }
      const tail = src.subarray(si);
      out.set(tail, di);
      di += tail.length;
      return out.subarray(0, di);
    }

    const patched = patchResets(data);
    console.log(`Original: ${data.length} bytes, patched: ${patched.length} bytes`);

    let baseline: string[] | null = null;
    const corruptReps: number[] = [];

    for (let rep = 0; rep < 30; rep++) {
      term.write(patched);
      term.wasmTerm!.update();
      const text = getViewportText(term);

      if (!baseline) { baseline = text; continue; }
      if (countDiffs(text, baseline) > 0) corruptReps.push(rep);
    }

    console.log(`With workaround: corrupt at [${corruptReps.join(', ')}] (${corruptReps.length}/30)`);
    expect(corruptReps.length).toBe(0);

    term.dispose();
  });

  /**
   * Both getViewport() and getLine() return the same wrong data,
   * proving the corruption is in the WASM ring buffer, not the API layer.
   */
  test('getViewport and getLine agree at the corrupt state', async () => {
    const term = await createIsolatedTerminal({ cols: 160, rows: 39, scrollback: 10_000_000 });
    const container = document.createElement('div');
    term.open(container);

    let baseline: string[] | null = null;

    for (let rep = 0; rep < 30; rep++) {
      term.write(data);
      term.wasmTerm!.update();
      const text = getViewportText(term);
      if (!baseline) { baseline = text; continue; }
      if (countDiffs(text, baseline) > 0) break; // stop at first corruption
    }

    // Compare APIs at whatever state we're in (corrupt or not)
    const vpText = getViewportText(term);
    let mismatches = 0;
    for (let row = 0; row < term.rows; row++) {
      const line = term.wasmTerm?.getLine(row);
      if (!line) continue;
      const lineText = line.map(c => String.fromCodePoint(c.codepoint || 32)).join('').trimEnd();
      if (vpText[row] !== lineText) mismatches++;
    }

    expect(mismatches).toBe(0);
    term.dispose();
  });
});

/**
 * Verify the scrollback bytes fix.
 *
 * Root cause: scrollbackLimit is passed as a line count (e.g. 10000)
 * but ghostty's Screen.init() interprets max_scrollback as bytes.
 * Native ghostty defaults to 10,000,000 (10MB). Passing 10,000 gives
 * only ~10KB, causing premature page pruning after ~500 rows.
 *
 * Fix: convert line count to bytes before passing to WASM.
 */

import { describe, expect, test } from 'bun:test';
import { createIsolatedTerminal } from './test-helpers';
import type { Terminal } from './terminal';

const ESC = '\x1b';

function generateTestOutput(): Uint8Array {
  const lines: string[] = [];
  lines.push(`${ESC}[1m${'═'.repeat(80)}${ESC}[0m`);
  lines.push('');
  lines.push(`${ESC}[1m── COLORS ──${ESC}[0m`);
  for (let row = 0; row < 8; row++) {
    let line = '';
    for (let i = 0; i < 32; i++) {
      line += `${ESC}[48;5;${row * 32 + i}m  ${ESC}[0m`;
    }
    lines.push(line);
  }
  lines.push(`${ESC}[1m── GRADIENTS ──${ESC}[0m`);
  for (let row = 0; row < 6; row++) {
    let line = '';
    for (let i = 0; i < 80; i++) {
      const r = Math.floor(Math.sin(i * 0.08 + row) * 127 + 128);
      const g = Math.floor(Math.sin(i * 0.08 + row + 2) * 127 + 128);
      const b = Math.floor(Math.sin(i * 0.08 + row + 4) * 127 + 128);
      line += `${ESC}[48;2;${r};${g};${b}m ${ESC}[0m`;
    }
    lines.push(line);
  }
  lines.push(`${ESC}[1m── ATTRIBUTES ──${ESC}[0m`);
  lines.push(`  ${ESC}[1mBold${ESC}[0m ${ESC}[3mItalic${ESC}[0m ${ESC}[4mUnderline${ESC}[0m ${ESC}[7mReverse${ESC}[0m`);
  lines.push(`${ESC}[1m── UNICODE ──${ESC}[0m`);
  lines.push('  ┌──────────┬──────────┐');
  lines.push('  │  Cell A   │  Cell B   │');
  lines.push('  ├──────────┼──────────┤');
  lines.push('  │  Cell C   │  Cell D   │');
  lines.push('  └──────────┴──────────┘');
  for (let section = 0; section < 4; section++) {
    lines.push(`${ESC}[1m── SECTION ${section + 5} ──${ESC}[0m`);
    for (let row = 0; row < 8; row++) {
      let line = '  ';
      for (let i = 0; i < 60; i++) {
        line += `${ESC}[38;5;${(section * 64 + row * 8 + i) % 256}m*${ESC}[0m`;
      }
      lines.push(line);
    }
  }
  lines.push('');
  lines.push('═'.repeat(80));
  lines.push('  ✓ Test complete');
  lines.push('═'.repeat(80));
  lines.push('');
  return new TextEncoder().encode(lines.join('\r\n') + '\r\n');
}

function getViewportText(term: Terminal): string[] {
  const viewport = term.wasmTerm!.getViewport();
  const cols = term.cols;
  const rows: string[] = [];
  for (let row = 0; row < term.rows; row++) {
    let text = '';
    for (let col = 0; col < cols; col++) {
      const c = viewport[row * cols + col];
      if (c.width === 0) continue;
      text += c.codepoint > 32 ? String.fromCodePoint(c.codepoint) : ' ';
    }
    rows.push(text.trimEnd());
  }
  return rows;
}

