      for (let run = 1; run <= 10; run++) {
        const output = generateEscapeHeavyOutput(run);
        term.write(output);
        term.wasmTerm!.update();

        // Compare every row: getViewport vs getLine
        for (let row = 0; row < term.rows; row++) {
          const viewportText = getViewportRowText(term, row);
          const lineText = getLineRowText(term, row);
          expect(viewportText).toBe(lineText);
        }
      }

      term.dispose();
    });

    test('getViewport returns identical data on consecutive calls', async () => {
      const term = await createIsolatedTerminal({ cols: 140, rows: 40, scrollback: 10000 });
      const container = document.createElement('div');
      term.open(container);

      for (let run = 1; run <= 10; run++) {
        const output = generateEscapeHeavyOutput(run);
        term.write(output);
        term.wasmTerm!.update();

        const viewport1 = term.wasmTerm!.getViewport();
        const snapshot1 = viewport1.map((c) => ({
          codepoint: c.codepoint,
          fg_r: c.fg_r,
          fg_g: c.fg_g,
          fg_b: c.fg_b,
          bg_r: c.bg_r,
          bg_g: c.bg_g,
          bg_b: c.bg_b,
          flags: c.flags,
          width: c.width,
        }));

        const viewport2 = term.wasmTerm!.getViewport();
        const snapshot2 = viewport2.map((c) => ({
          codepoint: c.codepoint,
          fg_r: c.fg_r,
          fg_g: c.fg_g,
          fg_b: c.fg_b,
          bg_r: c.bg_r,
          bg_g: c.bg_g,
          bg_b: c.bg_b,
          flags: c.flags,
          width: c.width,
        }));

        expect(snapshot1).toEqual(snapshot2);
      }

      term.dispose();
    });
  });

  describe('row-merge detection with marked lines', () => {
    test('no viewport row contains markers from two different lines', async () => {
      const term = await createIsolatedTerminal({ cols: 140, rows: 40, scrollback: 10000 });
      const container = document.createElement('div');
      term.open(container);

      const linesPerRun = 45;

      for (let run = 1; run <= 10; run++) {
        const output = generateMarkedOutput(run, linesPerRun);
        term.write(output);
        term.wasmTerm!.update();

        // Check each viewport row for multiple markers
        for (let row = 0; row < term.rows; row++) {
          const text = getViewportRowText(term, row);
          // Find all R##L## markers in this row
          const markers = text.match(/R\d{2}L\d{2}/g) || [];
          const uniqueMarkers = new Set(markers);
          // A row should contain at most one unique marker
          if (uniqueMarkers.size > 1) {
            throw new Error(
              `Run ${run}, row ${row}: found ${uniqueMarkers.size} different markers in one row: ${[...uniqueMarkers].join(', ')}\n` +
              `Row content: "${text}"`
            );
          }
        }
      }

      term.dispose();
    });

    test('markers remain intact after accumulating scrollback', async () => {
      const term = await createIsolatedTerminal({ cols: 140, rows: 40, scrollback: 10000 });
      const container = document.createElement('div');
      term.open(container);

      const linesPerRun = 45;

      for (let run = 1; run <= 10; run++) {
        const output = generateMarkedOutput(run, linesPerRun);
        term.write(output);
        term.wasmTerm!.update();

        // Verify viewport rows containing markers have the correct format
        for (let row = 0; row < term.rows; row++) {
          const text = getViewportRowText(term, row);
          const match = text.match(/R(\d{2})L(\d{2})/);
          if (match) {
            const markerRun = parseInt(match[1], 10);
            const markerLine = parseInt(match[2], 10);
            // The marker should reference a valid run/line
            expect(markerRun).toBeGreaterThanOrEqual(1);
            expect(markerRun).toBeLessThanOrEqual(run);
            expect(markerLine).toBeGreaterThanOrEqual(0);
            expect(markerLine).toBeLessThan(linesPerRun);
          }
        }
      }

      term.dispose();
    });
  });

  describe('viewport stability across page boundaries', () => {
    test('viewport consistent when output exceeds single page size', async () => {
      // Use smaller scrollback to force page recycling sooner
      const term = await createIsolatedTerminal({ cols: 140, rows: 40, scrollback: 500 });
      const container = document.createElement('div');
      term.open(container);

      // Write enough to overflow scrollback multiple times
      for (let run = 1; run <= 20; run++) {
        const output = generateMarkedOutput(run, 45);
        term.write(output);
        term.wasmTerm!.update();

        // Verify getViewport and getLine still agree
        for (let row = 0; row < term.rows; row++) {
          const viewportText = getViewportRowText(term, row);
          const lineText = getLineRowText(term, row);
          expect(viewportText).toBe(lineText);
        }

        // Check no row merging
        for (let row = 0; row < term.rows; row++) {
          const text = getViewportRowText(term, row);
          const markers = text.match(/R\d{2}L\d{2}/g) || [];
          const uniqueMarkers = new Set(markers);
          if (uniqueMarkers.size > 1) {
            throw new Error(
              `Run ${run}, row ${row}: row merge detected with ${uniqueMarkers.size} markers: ${[...uniqueMarkers].join(', ')}\n` +
              `Row content: "${text}"`
            );
          }
        }
      }

      term.dispose();
    });

    test('viewport consistent with large scrollback that triggers recycling', async () => {
      // Very small scrollback to force aggressive recycling
      const term = await createIsolatedTerminal({ cols: 140, rows: 40, scrollback: 100 });
      const container = document.createElement('div');
      term.open(container);

      for (let run = 1; run <= 15; run++) {
        const output = generateEscapeHeavyOutput(run);
        term.write(output);
        term.wasmTerm!.update();

        // getViewport and getLine must agree
        for (let row = 0; row < term.rows; row++) {
          const viewportText = getViewportRowText(term, row);
          const lineText = getLineRowText(term, row);
          expect(viewportText).toBe(lineText);
        }
      }

      term.dispose();
    });
  });
});

/**
 * Tests for Canvas Renderer
 *
 * Note: Most renderer tests are visual and require a browser environment.
 * These tests verify non-visual aspects like theme configuration.
 * Full visual tests are in examples/renderer-demo.html
 */

import { describe, expect, spyOn, test } from 'bun:test';
import { Ghostty } from './ghostty';
import { CanvasRenderer, DEFAULT_THEME } from './renderer';
import type { GhosttyCell } from './types';
import { CellFlags } from './types';

function mockCanvas() {
  const originalGetContext = HTMLCanvasElement.prototype.getContext;
  const fillRects: Array<{ color: string; rect: [number, number, number, number] }> = [];
  const transforms: Array<[number, number, number, number, number, number]> = [];
  const fillTextTransforms: Array<[number, number, number, number, number, number]> = [];
  const measuredFontSizes: number[] = [];
  const drawImages: Array<{ width: number; height: number; x: number; y: number }> = [];
  const tints: Array<{ color: string; alpha: number; width: number; height: number }> = [];
  const paths: Array<[number, number, number, number]> = [];
  let fillTextCount = 0;
  let strokeCount = 0;
  let clipCount = 0;

  HTMLCanvasElement.prototype.getContext = function (contextType: string, options?: any) {
    if (contextType !== '2d') return originalGetContext.call(this, contextType, options);
    const stack: Array<[number, number, number, number, number, number]> = [];
    let transform: [number, number, number, number, number, number] = [1, 0, 0, 1, 0, 0];

    return {
      canvas: this,
      fillStyle: '#000000',
      strokeStyle: '#000000',
      font: '15px monospace',
      textAlign: 'start',
      textBaseline: 'alphabetic',
      globalAlpha: 1,
      globalCompositeOperation: 'source-over',
      lineWidth: 1,
      measureText(this: { font: string }, text: string) {
        const size = Number.parseFloat(this.font);
        measuredFontSizes.push(size);
        return {
          width: text === 'M' ? size * 0.51 : size,
          actualBoundingBoxAscent: size * 0.7,
          actualBoundingBoxDescent: size * 0.2,
        };
      },
      fillRect(this: { fillStyle: string }, x: number, y: number, width: number, height: number) {
        fillRects.push({ color: this.fillStyle, rect: [x, y, width, height] });
        if ((this as any).globalCompositeOperation === 'source-in') {
          tints.push({
            color: this.fillStyle,
            alpha: (this as any).globalAlpha,
            width,
            height,
          });
        }
      },
      setTransform(a: number, b: number, c: number, d: number, e: number, f: number) {
        transform = [a, b, c, d, e, f];
        transforms.push(transform);
      },
      clearRect: () => {},
      fillText: () => {
        fillTextCount++;
        fillTextTransforms.push(transform);
      },
      createImageData: (width: number, height: number) => ({
        data: new Uint8ClampedArray(width * height * 4),
        width,
        height,
      }),
      putImageData: () => {},
      drawImage: (image: HTMLCanvasElement, x: number, y: number) => {
        drawImages.push({ width: image.width, height: image.height, x, y });
      },
      beginPath: () => {},
      moveTo: () => {},
      lineTo: () => {},
      stroke: () => strokeCount++,
      rect: (x: number, y: number, width: number, height: number) =>
        paths.push([x, y, width, height]),
      clip: () => clipCount++,
      save: () => stack.push(transform),
      restore: () => {
        transform = stack.pop() ?? transform;
      },
    } as any;
  };

  return {
    fillRects,
    transforms,
    fillTextTransforms,
    measuredFontSizes,
    drawImages,
    tints,
    paths,
    get fillTextCount() {
      return fillTextCount;
    },
    get strokeCount() {
      return strokeCount;
    },
    get clipCount() {
      return clipCount;
    },
    restore: () => {
      HTMLCanvasElement.prototype.getContext = originalGetContext;
    },
  };
}

function cell(bg_r: number, bg_g: number, bg_b: number): GhosttyCell {
  return {
    codepoint: 32,
    fg_r: 255,
    fg_g: 255,
    fg_b: 255,
    bg_r,
    bg_g,
    bg_b,
    flags: 0,
    width: 1,
    hyperlink_id: 0,
    grapheme_len: 0,
  };
}

function buffer(
  line: GhosttyCell[] | null,
  cols: number,
  rows: number = 1,
  cursor = { x: 0, y: 0, visible: false }
) {
  return {
    getLine: () => line,
    getCursor: () => cursor,
    getDimensions: () => ({ cols, rows }),
    isRowDirty: () => true,
    clearDirty: () => {},
  };
}

